    10→/**
    11→ * Initialize scroll-based card animations
    12→ */
    13→function initCardAnimations() {
    14→    const cards = document.querySelectorAll('.card[data-animate]');
    15→
    16→    if (!cards.length) return;
    17→
    18→    const observer = new IntersectionObserver(
    19→        (entries) => {
    20→            entries.forEach((entry) => {
    21→                if (entry.isIntersecting) {
    22→                    entry.target.classList.add('visible');
    23→                }
    24→            });
    25→        },
    26→        { threshold: 0.1 }
    27→    );
    28→
    29→    cards.forEach((card) => observer.observe(card));
    30→}
