   909→    class PowerFlowEngine {
   910→        constructor(caseData) {
   911→            this.baseMVA = caseData.baseMVA;
   912→            this.busData = JSON.parse(JSON.stringify(caseData.bus));
   913→            this.genData = JSON.parse(JSON.stringify(caseData.gen));
   914→            this.branchData = JSON.parse(JSON.stringify(caseData.branch));
   915→            
   916→            this.nBus = this.busData.length;
   917→            this.nBranch = this.branchData.length;
   918→            
   919→            this.V = [];
   920→            this.delta = [];
   921→            this.Pgen = [];
   922→            this.Qgen = [];
   923→            
   924→            this.slackBus = -1;
   925→            this.pvBuses = [];
   926→            this.pqBuses = [];
   927→            
   928→            this.Ybus = { re: [], im: [] };
   929→            
   930→            this.iteration = 0;
   931→            this.converged = false;
   932→            this.errorHistory = [];
   933→            this.maxPError = 0;
   934→            this.maxQError = 0;
   935→            
   936→            this.initialize();
   937→        }
   938→
   939→        initialize() {
   940→            for (let i = 0; i < this.nBus; i++) {
   941→                const bus = this.busData[i];
   942→                this.V[i] = bus[7];
   943→                this.delta[i] = bus[8] * Math.PI / 180;
   944→                
   945→                if (bus[1] === 3) {
   946→                    this.slackBus = i;
   947→                } else if (bus[1] === 2) {
   948→                    this.pvBuses.push(i);
   949→                } else {
   950→                    this.pqBuses.push(i);
   951→                }
   952→            }
   953→
   954→            this.Pgen = new Array(this.nBus).fill(0);
   955→            this.Qgen = new Array(this.nBus).fill(0);
   956→            
   957→            for (const gen of this.genData) {
   958→                const busIdx = gen[0] - 1;
   959→                this.Pgen[busIdx] += gen[1] / this.baseMVA;
   960→                this.Qgen[busIdx] += gen[2] / this.baseMVA;
   961→                
   962→                if (this.pvBuses.includes(busIdx) || busIdx === this.slackBus) {
   963→                    this.V[busIdx] = gen[5];
   964→                }
   965→            }
   966→
   967→            this.buildYbus();
   968→            
   969→            this.iteration = 0;
   970→            this.converged = false;
   971→            this.errorHistory = [];
   972→        }
   973→
   974→        buildYbus() {
   975→            for (let i = 0; i < this.nBus; i++) {
   976→                this.Ybus.re[i] = new Array(this.nBus).fill(0);
   977→                this.Ybus.im[i] = new Array(this.nBus).fill(0);
   978→            }
   979→
   980→            for (const branch of this.branchData) {
   981→                const from = branch[0] - 1;
   982→                const to = branch[1] - 1;
   983→                let r = branch[2];
   984→                let x = branch[3];
   985→                const b = branch[4];
   986→                const tap = branch[8] || 1;
   987→                
   988→                // Handle zero impedance (transformers)
   989→                if (Math.abs(r) < 1e-8 && Math.abs(x) < 1e-8) continue;
   990→                if (Math.abs(r) < 1e-8) r = 1e-6;
   991→                if (Math.abs(x) < 1e-8) x = 1e-6;
   992→                
   993→                const z2 = r * r + x * x;
   994→                const g = r / z2;
   995→                const bSeries = -x / z2;
   996→                
   997→                const tapRatio = tap === 0 ? 1 : tap;
   998→                
   999→                this.Ybus.re[from][to] -= g / tapRatio;
  1000→                this.Ybus.im[from][to] -= bSeries / tapRatio;
  1001→                this.Ybus.re[to][from] -= g / tapRatio;
  1002→                this.Ybus.im[to][from] -= bSeries / tapRatio;
  1003→                
  1004→                this.Ybus.re[from][from] += g / (tapRatio * tapRatio);
  1005→                this.Ybus.im[from][from] += bSeries / (tapRatio * tapRatio) + b / 2;
  1006→                this.Ybus.re[to][to] += g;
  1007→                this.Ybus.im[to][to] += bSeries + b / 2;
  1008→            }
  1009→
  1010→            for (let i = 0; i < this.nBus; i++) {
  1011→                const Gs = this.busData[i][4] / this.baseMVA;
  1012→                const Bs = this.busData[i][5] / this.baseMVA;
  1013→                this.Ybus.re[i][i] += Gs;
  1014→                this.Ybus.im[i][i] += Bs;
  1015→            }
  1016→        }
  1017→
  1018→        calcPowerInjection() {
  1019→            const P = new Array(this.nBus).fill(0);
  1020→            const Q = new Array(this.nBus).fill(0);
  1021→
  1022→            for (let i = 0; i < this.nBus; i++) {
  1023→                for (let j = 0; j < this.nBus; j++) {
  1024→                    const Gij = this.Ybus.re[i][j];
  1025→                    const Bij = this.Ybus.im[i][j];
  1026→                    const thetaij = this.delta[i] - this.delta[j];
  1027→                    
  1028→                    P[i] += this.V[i] * this.V[j] * (Gij * Math.cos(thetaij) + Bij * Math.sin(thetaij));
  1029→                    Q[i] += this.V[i] * this.V[j] * (Gij * Math.sin(thetaij) - Bij * Math.cos(thetaij));
  1030→                }
  1031→            }
  1032→
  1033→            return { P, Q };
  1034→        }
  1035→
  1036→        calcMismatch() {
  1037→            const { P, Q } = this.calcPowerInjection();
  1038→            const deltaP = [];
  1039→            const deltaQ = [];
  1040→
  1041→            for (let i = 0; i < this.nBus; i++) {
  1042→                if (i === this.slackBus) continue;
  1043→                
  1044→                const Pload = this.busData[i][2] / this.baseMVA;
  1045→                const Qload = this.busData[i][3] / this.baseMVA;
  1046→                const Pspec = this.Pgen[i] - Pload;
  1047→                const Qspec = this.Qgen[i] - Qload;
  1048→                
  1049→                deltaP.push({ bus: i, value: Pspec - P[i] });

